import React from "react";

export default function PollResults({ poll }) {
  if (!poll) return null;

  const total = poll.results?.reduce((a, b) => a + b, 0) || 0;

  return (
    <div className="results-shell">
      <div className="results-header-row">
        <span className="results-section-title">Question</span>
      </div>

      <div className="results-question-bar">
        <span className="results-question-text">{poll.question}</span>
      </div>

      <div className="results-options-list">
        {poll.options.map((opt, idx) => {
          const count = poll.results?.[idx] || 0;
          const pct = total ? Math.round((count / total) * 100) : 0;
          const barWidth = Math.max(pct, pct > 0 ? 10 : 0); // small min width when >0

          return (
            <div className="result-option-row" key={idx}>
              <div className="d-flex align-items-center w-100">
                {/* left: numbered circle + text */}
                <div className="d-flex align-items-center flex-grow-1">
                  <div className="result-option-index">{idx + 1}</div>
                  <div className="result-option-label">{opt}</div>
                </div>

                {/* right: percentage text */}
                <div className="result-option-percent">{pct}%</div>
              </div>

              {/* bootstrap progress bar */}
              <div className="progress result-option-progress">
                <div
                  className="progress-bar result-option-progress-bar"
                  role="progressbar"
                  style={{ width: `${barWidth}%` }}
                  aria-valuenow={pct}
                  aria-valuemin="0"
                  aria-valuemax="100"
                />
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}
